import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"二冬","description":"","frontmatter":{"title":"二冬","date":"2026-11-17T00:00:00.000Z","seq":2,"categories":["美文","声律启蒙"],"collection":"《声律启蒙 · 上卷》","tags":["声律启蒙","清"],"poem":true,"poem_quote":false,"author":"佚名","source_book":"声律启蒙"},"headers":[],"relativePath":"blogs/声律启蒙·上卷/二冬.md","filePath":"blogs/声律启蒙·上卷/二冬.md"}'),r={name:"blogs/声律启蒙·上卷/二冬.md"};function p(l,e,_,c,n,i){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="二冬" tabindex="-1">二冬 <a class="header-anchor" href="#二冬" aria-label="Permalink to &quot;二冬&quot;">​</a></h1><p class="poem-meta">清 · 佚名　·　上卷</p><div class="poem"><p class="poem-stanza">春对夏，秋对冬，暮鼓对晨钟。观山对玩水，绿竹对苍松。冯妇虎，叶公龙，舞蝶对鸣蛩。衔泥双紫燕，课蜜几黄蜂。春日园中莺恰恰，秋天塞外雁雍雍。秦岭云横，迢递八千远路；巫山雨洗，嵯峨十二危峰。</p><p class="poem-stanza">明对暗，淡对浓，上智对中庸。镜奁对衣笥，野杵对村舂。花灼烁，草蒙茸，九夏对三冬。台高名戏马，斋小号蟠龙。手擘蟹螯从毕卓，身披鹤氅自王恭。五老峰高，秀插云霄如玉笔；三姑石大，响传风雨若金镛。</p><p class="poem-stanza">仁对义，让对恭，禹舜对羲农。雪花对云叶，芍药对芙蓉。陈后主，汉中宗，绣虎对雕龙。柳塘风淡淡，花圃月浓浓。春日正宜朝看蝶，秋风那更夜闻蛩。战士邀功，必借干戈成勇武；逸民适志，须凭诗酒养疏慵。</p></div>',3)])])}const u=a(r,[["render",p]]);export{d as __pageData,u as default};
